// The brand faces (brand/design.md: Libre Baskerville for display, IBM Plex Sans for data and captions, IBM Plex Mono for
// citations), latin subsets as woff2 data URLs so a render needs no network and never assumes a font exists on the
// machine. Generated from the Google Fonts CSS (OFL licensed); regenerate rather than edit. Browser-safe.
export interface FontFaceSpec {
  family: string;
  style: string;
  weight: string; // one weight, or a variable range such as 400 700
  data: string; // data:font/woff2;base64,...
}
export const FONT_FACES: FontFaceSpec[] = [
  {
    family: 'IBM Plex Mono',
    style: 'normal',
    weight: '400',
    data: 'data:font/woff2;base64,',
  },
  {
    family: 'IBM Plex Sans',
    style: 'normal',
    weight: '400 600',
    data: 'data:font/woff2;base64,',
  },
  {
    family: 'Libre Baskerville',
    style: 'italic',
    weight: '400',
    data: 'data:font/woff2;base64,',
  },
  {
    family: 'Libre Baskerville',
    style: 'normal',
    weight: '400 700',
    data: 'data:font/woff2;base64,',
  },
];
/** The @font-face rules for every brand face, to put in a style element once per document. */
export const fontCss = () =>
  FONT_FACES.map(
    (f) =>
      `@font-face{font-family:'${f.family}';font-style:${f.style};font-weight:${f.weight};src:url(${f.data}) format('woff2')}`,
  ).join('\n');
